	// GOOSE_PATH_ROOT-based test sandboxes work.
	cmd.Env = os.Environ()
	out, err := cmd.CombinedOutput()
	if err != nil {
		return fmt.Errorf("goose session export %s: %w: %s", sessionID, err, string(out))
	}
	return nil
}

