package goose

import (
	"path/filepath"

	"github.com/entireio/external-agents/agents/entire-agent-goose/internal/protocol"
)

// Goose stores sessions in a SQLite database, not per-session files, so the
// session dir holds transcripts materialized by prepare-transcript /
// parse-hook via `goose session export`. They live under the repo's
// .entire/tmp scratch space like other external agents' prepared transcripts.

func sessionDir(repoPath string) string {
	if repoPath == "" {
		repoPath = protocol.RepoRoot()
	}
	return filepath.Join(repoPath, ".entire", "tmp", "goose")
}

func (a *Agent) GetSessionDir(repoPath string) (string, error) {
	return sessionDir(repoPath), nil
}

func (a *Agent) ResolveSessionFile(sessionDirPath, sessionID string) string {
	return filepath.Join(sessionDirPath, sessionID+".json")
}

// transcriptPath is the materialized export location for a session.
func transcriptPath(sessionID string) string {
	return filepath.Join(sessionDir(""), sessionID+".json")
}

