import type { ToolCall, ToolCallResult, ToolMixCategoryKey, TranscriptMessage } from "../../types"
import type { TranscriptParseResult, TranscriptParser } from "./types"

/**
 * Parser for Goose (Block's open-source coding agent) transcripts.
 *
 * Goose stores sessions in SQLite; the entire-agent-goose binary materializes
 * a transcript via `goose session export --format json`, which is what ends up
 * in checkpoint storage: a single JSON document with session metadata and a
 * `conversation` array. Message content blocks are camelCase:
 *
 *   {"type":"text","text":"..."}
 *   {"type":"toolRequest","id":"toolu_..","toolCall":{"status":"success",
 *     "value":{"name":"write","arguments":{"path":"...","content":"..."}}}}
 *   {"type":"toolResponse","id":"toolu_..","toolResult":{"status":"success",
 *     "value":{"content":[{"type":"text","text":"..."}],"isError":false}}}
 *
 * Tool responses arrive as user-role messages; they are folded into the
 * originating assistant tool call rather than rendered as user messages.
 */

interface GooseExport {
  id?: string
  created_at?: string
  model_config?: {
    model_name?: string
  }
  conversation?: GooseMessage[]
  [key: string]: unknown
}

interface GooseMessage {
  id?: string
  role?: string
  created?: number
  content?: GooseContentBlock[]
}

interface GooseContentBlock {
  type?: string
  text?: string
  id?: string
  toolCall?: {
    status?: string
    value?: {
      name?: string
      arguments?: Record<string, unknown>
    }
  }
  toolResult?: {
    status?: string
    value?: {
      content?: { type?: string; text?: string }[]
      isError?: boolean
    }
  }
}

function parseGooseExport(content: string): GooseExport | null {
  try {
    const log = JSON.parse(content) as GooseExport
    if (!Array.isArray(log.conversation)) return null
    return log
  } catch {
    return null
  }
}

function messageTimestamp(message: GooseMessage, fallback: string): string {
  if (typeof message.created === "number" && Number.isFinite(message.created)) {
    return new Date(message.created * 1000).toISOString()
  }
  return fallback
}

function sessionCreated(log: GooseExport): string {
  if (typeof log.created_at === "string" && log.created_at) return log.created_at
  return new Date(0).toISOString()
}

function extractText(content: GooseMessage["content"]): string {
  if (!Array.isArray(content)) return ""

  return content
    .flatMap((block) => {
      if (block.type !== "text") return []
      if (typeof block.text !== "string" || !block.text.trim()) return []
      return [block.text]
    })
    .join("\n")
    .trim()
}

function extractToolCalls(content: GooseMessage["content"], timestamp: string): ToolCall[] {
  if (!Array.isArray(content)) return []

  return content
    .filter((block) => block.type === "toolRequest" && typeof block.toolCall?.value?.name === "string")
    .map((block) => ({
      id: block.id ?? crypto.randomUUID(),
      name: block.toolCall!.value!.name!,
      input: block.toolCall?.value?.arguments ?? {},
      timestamp,
    }))
}

function extractToolResults(messages: GooseMessage[]): Map<string, ToolCallResult> {
  const results = new Map<string, ToolCallResult>()

  for (const message of messages) {
    if (message.role !== "user" || !Array.isArray(message.content)) continue

    for (const block of message.content) {
      if (block.type !== "toolResponse" || !block.id || !block.toolResult) continue
      results.set(block.id, parseToolResult(block.toolResult))
    }
  }

  return results
}

function parseToolResult(toolResult: NonNullable<GooseContentBlock["toolResult"]>): ToolCallResult {
  const isError =
    toolResult.value?.isError === true ||
    (typeof toolResult.status === "string" && toolResult.status.toLowerCase() !== "success")

  const output = (toolResult.value?.content ?? [])
    .flatMap((block) => {
      if (block.type !== "text") return []
      if (typeof block.text !== "string" || !block.text) return []
      return [block.text]
    })
    .join("\n")

  const parsed: ToolCallResult = {
    type: isError ? "error" : "text",
  }
  if (output) parsed.output = output
  if (isError) parsed.error = output || toolResult.status || "Tool call failed"

  return parsed
}

function parseGooseMessages(log: GooseExport, fromIndex: number): TranscriptMessage[] {
  const conversation = log.conversation ?? []
  const created = sessionCreated(log)
  // Tool results can land after the offset boundary, so index them across
  // the whole conversation before slicing.
  const toolResultById = extractToolResults(conversation)
  const result: TranscriptMessage[] = []

  let pendingAssistantText: string[] = []
  let pendingToolCalls: ToolCall[] = []
  let pendingTimestamp: string | null = null
  let pendingId: string | null = null

  const flushAssistant = () => {
    if (pendingAssistantText.length === 0 && pendingToolCalls.length === 0) {
      pendingTimestamp = null
      pendingId = null
      return
    }

    for (const toolCall of pendingToolCalls) {
      const toolResult = toolResultById.get(toolCall.id)
      if (toolResult) toolCall.result = toolResult
    }

    result.push({
      id: pendingId ?? crypto.randomUUID(),
      role: "assistant",
      content: pendingAssistantText.join("\n\n").trim(),
      timestamp: pendingTimestamp ?? created,
      toolCalls: pendingToolCalls.length > 0 ? [...pendingToolCalls] : undefined,
    })

    pendingAssistantText = []
    pendingToolCalls = []
    pendingTimestamp = null
    pendingId = null
  }

  const startIndex = Math.max(0, fromIndex)
  for (let i = startIndex; i < conversation.length; i++) {
    const message = conversation[i]!
    const timestamp = messageTimestamp(message, created)

    if (message.role === "user") {
      // toolResponse-only user messages are tool results, not prompts.
      const text = extractText(message.content)
      if (!text) continue

      flushAssistant()
      result.push({
        id: message.id ?? crypto.randomUUID(),
        role: "user",
        content: text,
        timestamp,
      })
      continue
    }

    if (message.role === "assistant") {
      if (!pendingTimestamp) pendingTimestamp = timestamp
      if (!pendingId) pendingId = message.id ?? null

      const text = extractText(message.content)
      if (text) pendingAssistantText.push(text)
      pendingToolCalls.push(...extractToolCalls(message.content, timestamp))
    }
  }

  flushAssistant()
  return result
}

export class GooseParser implements TranscriptParser {
  readonly name = "Goose"
  readonly format = "json" as const

  parse(content: string): TranscriptParseResult {
    return this.parseFrom(content, 0)
  }

  parseFrom(content: string, offset: number): TranscriptParseResult {
    const log = parseGooseExport(content)
    if (!log) {
      return {
        messages: [],
        isFallback: false,
        warning: "Unable to parse Goose transcript",
      }
    }

    return {
      messages: parseGooseMessages(log, offset),
      isFallback: false,
    }
  }

  /**
   * Drop session metadata the parser doesn't read (extension_data, recipe,
   * token counters, ...) while keeping conversation content and the model.
   */
  strip(content: string): string {
    const log = parseGooseExport(content)
    if (!log) return content

    const stripped: GooseExport = {
      id: log.id,
      created_at: log.created_at,
      conversation: log.conversation,
    }
    if (log.model_config?.model_name) {
      stripped.model_config = { model_name: log.model_config.model_name }
    }
    return JSON.stringify(stripped)
  }

  classifyTool(call: ToolCall): ToolMixCategoryKey {
    // Strip goose's extension-qualified prefix (developer__shell -> shell).
    const name = call.name.includes("__") ? call.name.slice(call.name.lastIndexOf("__") + 2) : call.name
    if (name === "shell" || name === "bash") return "shell"
    if (name === "write" || name === "text_editor" || name === "edit" || name === "read" || name === "view") {
      return "fileOps"
    }
    if (name === "grep" || name === "glob" || name === "tree" || name === "analyze" || name === "search") {
      return "search"
    }
    if (name === "subagent" || name === "dynamic_task" || name === "task") return "agent"
    return "other"
  }

  extractSkillFromTool(call: ToolCall): string | null {
    if (call.name !== "load_skill" && !call.name.endsWith("__load_skill")) return null
    const name = call.input["name"] ?? call.input["skill"]
    return typeof name === "string" && name ? name : null
  }

  extractMcpServerFromTool(_call: ToolCall): string | null {
    return null
  }

  extractModel(content: string): string | null {
    const log = parseGooseExport(content)
    const model = log?.model_config?.model_name
    return typeof model === "string" && model ? model : null
  }
}

