      result.push({
        id: message.id ?? crypto.randomUUID(),
        role: "user",
        content: text,
        timestamp,
      })
      continue
    }

    if (message.role === "assistant") {
      if (!pendingTimestamp) pendingTimestamp = timestamp
      if (!pendingId) pendingId = message.id ?? null

      const text = extractText(message.content)
      if (text) pendingAssistantText.push(text)
      pendingToolCalls.push(...extractToolCalls(message.content, timestamp))
    }
  }

  flushAssistant()
  return result
}

export class GooseParser implements TranscriptParser {
  readonly name = "Goose"
  readonly format = "json" as const

  parse(content: string): TranscriptParseResult {
    return this.parseFrom(content, 0)
  }

  parseFrom(content: string, offset: number): TranscriptParseResult {
    const log = parseGooseExport(content)
    if (!log) {
      return {
        messages: [],
        isFallback: false,
        warning: "Unable to parse Goose transcript",
      }
    }

    return {
      messages: parseGooseMessages(log, offset),
      isFallback: false,
    }
  }

  /**
   * Drop session metadata the parser doesn't read (extension_data, recipe,
   * token counters, ...) while keeping conversation content and the model.
   */
  strip(content: string): string {
    const log = parseGooseExport(content)
    if (!log) return content

    const stripped: GooseExport = {
      id: log.id,
      created_at: log.created_at,
      conversation: log.conversation,
    }
    if (log.model_config?.model_name) {
      stripped.model_config = { model_name: log.model_config.model_name }
    }
    return JSON.stringify(stripped)
  }

  classifyTool(call: ToolCall): ToolMixCategoryKey {
    // Strip goose's extension-qualified prefix (developer__shell -> shell).
    const name = call.name.includes("__") ? call.name.slice(call.name.lastIndexOf("__") + 2) : call.name
    if (name === "shell" || name === "bash") return "shell"
    if (name === "write" || name === "text_editor" || name === "edit" || name === "read" || name === "view") {
      return "fileOps"
    }
    if (name === "grep" || name === "glob" || name === "tree" || name === "analyze" || name === "search") {
      return "search"
    }
    if (name === "subagent" || name === "dynamic_task" || name === "task") return "agent"
    return "other"
  }

  extractSkillFromTool(call: ToolCall): string | null {
    if (call.name !== "load_skill" && !call.name.endsWith("__load_skill")) return null
    const name = call.input["name"] ?? call.input["skill"]
    return typeof name === "string" && name ? name : null
  }

  extractMcpServerFromTool(_call: ToolCall): string | null {
    return null
  }

  extractModel(content: string): string | null {
    const log = parseGooseExport(content)
    const model = log?.model_config?.model_name
    return typeof model === "string" && model ? model : null
  }
}

