import { GooseParser } from "./goose-parser"

// Trimmed `goose session export --format json` document captured from
// goose 1.37.0 (same fixture family as entire-agent-goose's unit tests).
const exportFixture = JSON.stringify({
  id: "20260611_1",
  working_dir: "/tmp/workspace",
  name: "File verification request",
  created_at: "2026-06-11T11:02:34Z",
  accumulated_input_tokens: 5650,
  accumulated_output_tokens: 124,
  provider_name: "openrouter",
  model_config: { model_name: "anthropic/claude-opus-4.6", context_limit: 1000000 },
  extension_data: { "enabled_extensions.v0": { extensions: [{ name: "developer" }] } },
  conversation: [
    {
      id: "msg_1",
      role: "user",
      created: 1781175769,
      content: [{ type: "text", text: "Create a file named verify.txt" }],
    },
    {
      id: "msg_2",
      role: "assistant",
      created: 1781175772,
      content: [
        {
          type: "toolRequest",
          id: "toolu_1",
          toolCall: {
            status: "success",
            value: {
              name: "write",
              arguments: { path: "/tmp/workspace/verify.txt", content: "ENTIRE_VERIFY_FILE" },
            },
          },
        },
      ],
    },
    {
      id: "msg_3",
      role: "user",
      created: 1781175773,
      content: [
        {
          type: "toolResponse",
          id: "toolu_1",
          toolResult: {
            status: "success",
            value: {
              content: [{ type: "text", text: "Created /tmp/workspace/verify.txt (1 lines)" }],
              isError: false,
            },
          },
        },
      ],
    },
    {
      id: "msg_4",
      role: "assistant",
      created: 1781175775,
      content: [{ type: "text", text: "ENTIRE_VERIFY_OK" }],
    },
  ],
})

describe("GooseParser", () => {
  const parser = new GooseParser()

  it("parses user prompts, assistant text, and tool calls with folded results", () => {
    const result = parser.parse(exportFixture)

    expect(result.isFallback).toBe(false)
    expect(result.warning).toBeUndefined()
    expect(result.messages).toHaveLength(2)

    const [user, assistant] = result.messages
    expect(user).toMatchObject({
      id: "msg_1",
      role: "user",
      content: "Create a file named verify.txt",
      timestamp: new Date(1781175769 * 1000).toISOString(),
    })

    // The toolResponse user message must fold into the assistant turn, and
    // consecutive assistant messages merge into one.
    expect(assistant!.role).toBe("assistant")
    expect(assistant!.content).toBe("ENTIRE_VERIFY_OK")
    expect(assistant!.toolCalls).toHaveLength(1)
    expect(assistant!.toolCalls![0]).toMatchObject({
      id: "toolu_1",
      name: "write",
      input: { path: "/tmp/workspace/verify.txt", content: "ENTIRE_VERIFY_FILE" },
      result: {
        type: "text",
        output: "Created /tmp/workspace/verify.txt (1 lines)",
      },
    })
  })

  it("parses from a message-index offset", () => {
    const result = parser.parseFrom(exportFixture, 3)

    expect(result.messages).toHaveLength(1)
    expect(result.messages[0]).toMatchObject({
      role: "assistant",
      content: "ENTIRE_VERIFY_OK",
    })
  })

  it("marks failed tool calls as errors", () => {
    const doc = JSON.parse(exportFixture)
    doc.conversation[2].content[0].toolResult = {
      status: "error",
      value: { content: [{ type: "text", text: "permission denied" }], isError: true },
    }
    const result = parser.parse(JSON.stringify(doc))

    const toolCall = result.messages[1]!.toolCalls![0]!
    expect(toolCall.result).toMatchObject({ type: "error", error: "permission denied" })
  })

  it("warns on unparseable content", () => {
    expect(parser.parse("not json").warning).toBeDefined()
    expect(parser.parse(`{"id":"x"}`).warning).toBeDefined()
  })

  it("strips session metadata the parser does not read", () => {
    const stripped = parser.strip(exportFixture)
    const doc = JSON.parse(stripped)

    expect(doc.extension_data).toBeUndefined()
    expect(doc.accumulated_input_tokens).toBeUndefined()
    expect(doc.conversation).toHaveLength(4)
    expect(doc.model_config.model_name).toBe("anthropic/claude-opus-4.6")

    // Stripped output must still parse identically.
    expect(parser.parse(stripped).messages).toEqual(parser.parse(exportFixture).messages)
  })

  it("extracts the model from the export", () => {
    expect(parser.extractModel(exportFixture)).toBe("anthropic/claude-opus-4.6")
    expect(parser.extractModel("not json")).toBeNull()
  })

  it("classifies goose developer tools", () => {
    const call = (name: string) => ({ id: "t", name, input: {}, timestamp: "" })
    expect(parser.classifyTool(call("shell"))).toBe("shell")
    expect(parser.classifyTool(call("developer__shell"))).toBe("shell")
    expect(parser.classifyTool(call("write"))).toBe("fileOps")
    expect(parser.classifyTool(call("text_editor"))).toBe("fileOps")
    expect(parser.classifyTool(call("tree"))).toBe("search")
    expect(parser.classifyTool(call("analyze"))).toBe("search")
    expect(parser.classifyTool(call("dynamic_task"))).toBe("agent")
    expect(parser.classifyTool(call("load_skill"))).toBe("other")
  })

  it("extracts skill names from load_skill calls", () => {
    expect(
      parser.extractSkillFromTool({ id: "t", name: "load_skill", input: { name: "web-app" }, timestamp: "" }),
    ).toBe("web-app")
    expect(parser.extractSkillFromTool({ id: "t", name: "write", input: {}, timestamp: "" })).toBeNull()
  })
})

